class _Node:
    def __init__(self, name):
        if not isinstance(name, str) or not name.strip():
            raise ValueError("Name required")
        self._name = name.strip()
        self._parent = None

    @property
    def name(self):
        return self._name

    @property
    def parent(self):
        return self._parent

    def find(self, name):
        if self._name == name:
            return self
        for child in self._children_of():
            found = child.find(name)
            if found is not None:
                return found
        return None

    def path(self, name):
        if self._name == name:
            return [self._name]
        for child in self._children_of():
            below = child.path(name)
            if below is not None:
                return [self._name] + below
        return None

    def _children_of(self):
        return ()


class Item(_Node):
    def __init__(self, name, price):
        super().__init__(name)
        if type(price) is not int or price < 0:
            raise ValueError("Price must be a non-negative integer")
        self.price = price

    @property
    def total(self):
        return self.price

    @property
    def count(self):
        return 1

    def lines(self):
        return [f"{self._name} {self.price // 100}.{self.price % 100:02d}"]


class Section(_Node):
    def __init__(self, name):
        super().__init__(name)
        self._children = []

    @property
    def children(self):
        return tuple(self._children)

    def _children_of(self):
        return self._children

    @property
    def total(self):
        return sum(child.total for child in self._children)

    @property
    def count(self):
        return sum(child.count for child in self._children)

    def add(self, *children):
        seen = set()
        for child in children:
            if not isinstance(child, _Node):
                raise ValueError("Not a menu node")
            ancestor = self
            while ancestor is not None:
                if ancestor is child:
                    raise ValueError("Cycle")
                ancestor = ancestor._parent
            if child._parent is not None or id(child) in seen:
                raise ValueError("Already in a section")
            seen.add(id(child))
        for child in children:
            child._parent = self
            self._children.append(child)
        return self

    def remove(self, child):
        if not isinstance(child, _Node) or child._parent is not self:
            raise ValueError("Not in this section")
        self._children.remove(child)
        child._parent = None

    def lines(self):
        result = [self._name + ":"]
        for child in self._children:
            result.extend("  " + line for line in child.lines())
        return result
